const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
const title = String($json.title ?? '').trim();
const selectedHook = String($json.selected_hook ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error('Fetch Next Publish Draft Item did not produce a valid content_id.');
}
if (!title) {
  throw new Error('Fetch Next Publish Draft Item did not produce a title.');
}
if (!selectedHook) {
  throw new Error('Fetch Next Publish Draft Item did not produce a selected_hook.');
}
return [{
  json: {
    content_id: contentId,
    title,
    category: String($json.category ?? 'general'),
    status: String($json.status ?? 'script_complete'),
    selected_hook: selectedHook,
    narration_script: String($json.narration_script ?? ''),
    brand_tone: 'cinematic, concise, credible',
    llm_instruction: 'Create a compact Instagram caption and relevant hashtags for a simple image post.',
    publish_status_after_success: 'draft'
  }
}];

return [{
  json: {
    content_id: $json.content_id,
    title: $json.title,
    category: $json.category,
    selected_hook: $json.selected_hook,
    prompt: {
      instruction: $json.llm_instruction,
      narration_script: $json.narration_script,
      brand_tone: $json.brand_tone,
      response_schema: {
        caption_final: 'string',
        hashtags_final: 'string'
      }
    },
    publish_status_after_success: $json.publish_status_after_success
  }
}];

if (!$json.content_id || !$json.title || !$json.selected_hook) {
  throw new Error('Build Caption Request did not produce the required caption context.');
}
const titleWords = $json.title
  .replace(/[^a-zA-Z0-9\s]/g, ' ')
  .split(/\s+/)
  .filter(Boolean)
  .slice(0, 3)
  .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase());
const categoryMap = {
  mystery: ['#MysteryTok', '#UnsolvedHistory'],
  history: ['#HistoryFacts', '#HiddenHistory'],
  general: ['#StoryPost', '#InterestingStories']
};
const mapped = categoryMap[String($json.category).toLowerCase()] ?? categoryMap.general;
const titleTags = titleWords.length ? [`#${titleWords.join('')}`] : [];
const defaultTags = ['#InstagramStories', '#Storytelling', '#CuriousMinds'];
const hashtags = [...new Set([...titleTags, ...mapped, ...defaultTags])].slice(0, 5).join(' ');
const caption = `${$json.selected_hook}\n\n${$json.title} in one short post: the detail that keeps this story alive.\n\nWould you have believed it at first glance?`;
return [{
  json: {
    content_id: $json.content_id,
    publish_status_after_success: $json.publish_status_after_success,
    caption_response: {
      caption_final: caption,
      hashtags_final: hashtags
    }
  }
}];

const response = $json.caption_response ?? {};
if (!$json.content_id) {
  throw new Error('Mock Caption Response did not provide content_id.');
}
if (!response.caption_final || !response.hashtags_final) {
  throw new Error('Mock Caption Response did not produce caption_final and hashtags_final.');
}
return [{
  json: {
    content_id: $json.content_id,
    publish_status_after_success: $json.publish_status_after_success,
    caption_final: response.caption_final,
    hashtags_final: response.hashtags_final
  }
}];

const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error(`Prepare Publish Draft SQL Values received an invalid content_id: ${contentId || '<empty>'}.`);
}
return [{
  json: {
    ...$json,
    content_id_sql: contentId,
    caption_final_sql: String($json.caption_final ?? '').replaceAll("'", "''"),
    hashtags_final_sql: String($json.hashtags_final ?? '').replaceAll("'", "''"),
    publish_status_sql: String($json.publish_status_after_success ?? 'draft').replaceAll("'", "''")
  }
}];
